"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79044"],{11937(e){e.exports=JSON.parse('{"id":"FIN-282","slug":"primary-market","term":"Primary Market","also_known_as":[],"difficulty":"Intermediate","definition":"The primary market is where new securities are created and sold for the first time, with the money going to the issuing company or government.","explanation":["When a company sells new shares or a government issues new bonds, the sale happens in the primary market. The issuer receives the money raised, which it can use for investment, expansion or to repay other debts.","The best-known example is an initial public offering (IPO), when a company sells shares to the public for the first time. Other examples include later sales of new shares by listed companies, new bond issues by companies and governments, and auctions of new government bonds.","Investment banks often help issuers in the primary market. They advise on pricing, find investors and may guarantee to buy any securities that are not sold, a service called underwriting.","For example, if a company issues 10 million new shares at 20 each, it raises 200 million, minus fees, in the primary market.","Once securities have been issued, they trade between investors in the secondary market, where the issuer does not receive any money from the trades."],"note":"","total":1500,"prev":{"slug":"price-volume-mix-analysis","term":"Price-Volume-Mix Analysis"},"next":{"slug":"prime-rate","term":"Prime Rate"}}')}}]);